class Counter:
    def __init__(self, stop):
        self.stop = stop
        self.current = 0
    def __iter__(self):
        return self
    def __next__(self):
        if self.current >= self.stop:
            raise StopIteration
        val = self.current
        self.current += 1
        return val

for n in Counter(3):
    print(n)
